def transform(grid):
    out = [row[:] for row in grid]
    # The repeating pattern consists of a background color alternating with
    # the other color; recolor the other-color cells bracketed by background.
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value != bg:
                left = row[c - 1] if c > 0 else None
                right = row[c + 1] if c + 1 < len(row) else None
                if left == bg and right == bg:
                    out[r][c] = 2
    return out
